Question 1: Predict the output of the following program. What does the following fun() do in general?  
            C++

    using namespace std;
int fun(int a, int b) 
{ 
    if (b == 0) 
        return 0; 
    if (b % 2 == 0) 
        return fun(a + a, b/2); 

    return fun(a + a, b/2) + a; 
} 

// Driver code
int main() 
{ 
    cout << fun(4, 3) ; 
    return 0; 
} 


